import{_ as n,o as i,c as l,a3 as t}from"./chunks/framework.BvvarXmc.js";const m=JSON.parse('{"title":"Panduan Login Pertama Kali","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-siswa/login-portal.md","filePath":"panduan-siswa/login-portal.md","lastUpdated":null}'),o={name:"panduan-siswa/login-portal.md"};function e(s,a,r,d,k,u){return i(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="panduan-login-pertama-kali" tabindex="-1">Panduan Login Pertama Kali <a class="header-anchor" href="#panduan-login-pertama-kali" aria-label="Permalink to &quot;Panduan Login Pertama Kali&quot;">​</a></h1><p>Ikuti langkah mudah di bawah ini untuk mengakses portal siswa untuk pertama kalinya.</p><hr><h2 id="_1-masuk-ke-halaman-login" tabindex="-1">1. Masuk ke Halaman Login <a class="header-anchor" href="#_1-masuk-ke-halaman-login" aria-label="Permalink to &quot;1. Masuk ke Halaman Login&quot;">​</a></h2><ol><li>Buka browser di HP atau laptop Anda (disarankan Google Chrome).</li><li>Akses alamat web sekolah yang diberikan oleh pihak Tata Usaha.</li><li>Pada halaman login: <ul><li><strong>Username</strong>: Masukkan <strong>Nomor Induk Siswa Nasional (NISN)</strong> Anda (contoh: <code>0051234567</code>).</li><li><strong>Kata Sandi (Password) Awal</strong>: Masukkan kata sandi default yang dibagikan pihak sekolah (biasanya kombinasi NISN atau tanggal lahir dalam format <code>DDMMYYYY</code>).</li></ul></li><li>Klik tombol <strong>Masuk (Login)</strong>.</li></ol><hr><h2 id="_2-mengubah-kata-sandi-pribadi" tabindex="-1">2. Mengubah Kata Sandi Pribadi <a class="header-anchor" href="#_2-mengubah-kata-sandi-pribadi" aria-label="Permalink to &quot;2. Mengubah Kata Sandi Pribadi&quot;">​</a></h2><p>Demi menjaga keamanan akun dan saldo dompet digital siswa, sangat dianjurkan untuk langsung mengubah kata sandi:</p><ol><li>Setelah berhasil masuk, klik ikon <strong>Profil Saya</strong> di pojok kanan atas layar.</li><li>Pilih menu <strong>Keamanan Akun / Ubah Password</strong>.</li><li>Masukkan kata sandi lama, lalu ketik kata sandi baru yang mudah Anda ingat namun sulit ditebak orang lain (minimal 8 karakter).</li><li>Klik <strong>Simpan Kata Sandi</strong>.</li></ol><div class="warning custom-block"><p class="custom-block-title">Jika Lupa Kata Sandi</p><p>Jangan panik! Hubungi Wali Kelas atau petugas Tata Usaha (TU) sekolah untuk mereset kata sandi akun Anda kembali ke setelan awal.</p></div>',10)])])}const h=n(o,[["render",e]]);export{m as __pageData,h as default};
